const Module = require('bare-module')
const acorn = require('acorn')
const walk = require('acorn-walk')
const b4a = require('b4a')

module.exports = disk_loader

// runs a js file and everything it requires straight from a drive (autodisk, hyperdrive or a checkout)
// nothing is copied to disk, and code can only require modules outside the drive if they are in builtins
// every file of the drive is loaded into memory first, so require() (which is sync) is answered right away,
// also with a computed name like require(name). a module thats not in the drive or builtins gives MODULE_NOT_FOUND
async function disk_loader ({ drive, file, builtins = {} }) {
  const files = await load(drive)
  const protocol = new Module.Protocol({ exists, read })
  const loader = new Module.Loader({ protocol, builtins, defaultType: Module.constants.SCRIPT })
  return loader.import(new URL('drive://' + file))

  function exists (url) { return files.has(url.pathname) }

  function read (url) {
    const data = files.get(url.pathname)
    if (!url.pathname.endsWith('.js')) return data
    const source = b4a.toString(data)
    refuse_dynamic_import(source, url)
    return source
  }
}

/***************************************
LOAD
reads every file of the drive into memory, an autodisk lists names and a hyperdrive lists entries
***************************************/
async function load (drive) {
  const files = new Map()
  for await (const item of await drive.list('/', { recursive: true })) {
    const name = item.key || item
    files.set(name, await drive.get(name))
  }
  return files
}

/***************************************
REFUSE DYNAMIC IMPORT
import() would load code around the loader, so drive code cant use it
***************************************/
function refuse_dynamic_import (source, url) {
  const ast = acorn.parse(source, { ecmaVersion: 'latest', sourceType: 'script' })
  walk.simple(ast, { ImportExpression () { throw new SyntaxError(`dynamic import is not allowed: ${url.href}`) } })
}
